	}))
	defer core.Close()

	s := newJurisdictionTokenSource(core.URL, "https://eu.example.io", "", "toothbrush", staticLogin(fakeLoginJWT(t, "eu")), noopRecord, core.Client())
	token, err := s.Token(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	if token != "fresh-jwt" || mints != 1 {
